const gate = async (store: Store, ctx: Ctx) => { needModule(ctx, "customers"); await needFeature(store, ctx, "crmPro"); };
const mgr = async (store: Store, ctx: Ctx) => { await gate(store, ctx); need(ctx, "manager"); };
const isOwner = (ctx: Ctx) => ctx.roles.includes("owner");
