async function loadCamp(store: Store, ctx: Ctx, id: unknown): Promise<Row> { const c = await store.get("crm_campaigns", String(id ?? "")); if (!mine(ctx, c)) throw new HttpError(404, "Campagne introuvable"); return c; }
