  if (name.length < 3) throw new HttpError(400, "Nom obligatoire (3 caractères au moins)"); let n; try { n = normRule(b); } catch (e) { throw new HttpError(400, (e as Error).message); } const k = rkey(b as Record<string, unknown>); const id = `ru${sha(`${ctx.tenantId}|${ctx.shopId}|rule|${k}`).slice(0, 30)}`; if (await store.get("crm_rules", id)) return { id, duplicate: true };
  if (n.task.owner !== "portfolio" && n.task.owner !== "creator" && !(await names(store, ctx)).has(n.task.owner)) throw new HttpError(400, "Responsable inconnu"); await store.batch([{ kind: "create", table: "crm_rules", id, tenantId: ctx.tenantId, data: { ...MIN(ctx), name, trigger: n.trigger, params: JSON.stringify(n.params), task: JSON.stringify(n.task), enabled: false, createdBy: ctx.userId, version: 1 } }, aud(ctx, "crmpro.rule.create", `${name} ${n.trigger}`)]); return { id, duplicate: false };
